import{c as a,Q as o,j as r,m as d}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"Profil Hotspot","description":"","frontmatter":{},"headers":[],"relativePath":"panduan/hotspot/profil.md","filePath":"panduan/hotspot/profil.md"}'),i={name:"panduan/hotspot/profil.md"};function e(n,t,s,l,p,h){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="profil-hotspot" tabindex="-1">Profil Hotspot <a class="header-anchor" href="#profil-hotspot" aria-label="Permalink to &quot;Profil Hotspot&quot;">​</a></h1><p>Profil hotspot mendefinisikan batasan yang berlaku untuk voucher yang dibuat — durasi akses, batas kuota, dan kecepatan.</p><hr><h2 id="membuat-profil-hotspot" tabindex="-1">Membuat Profil Hotspot <a class="header-anchor" href="#membuat-profil-hotspot" aria-label="Permalink to &quot;Membuat Profil Hotspot&quot;">​</a></h2><ol><li>Buka router → <strong>Hotspot → Profil</strong></li><li>Klik <strong>+ Tambah Profil</strong></li><li>Isi form:</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Nama Profil</strong></td><td>Nama profil di MikroTik, misal <code>1jam</code> atau <code>sehari</code></td></tr><tr><td><strong>Nama Layanan</strong></td><td>Nama yang tampil kepada pengguna, misal <code>Paket 1 Jam</code></td></tr><tr><td><strong>Validitas</strong></td><td>Durasi akses voucher</td></tr><tr><td><strong>Satuan Validitas</strong></td><td><code>menit</code>, <code>jam</code>, atau <code>hari</code></td></tr><tr><td><strong>Batas Kuota</strong></td><td>Batas data (MB/GB). Kosongkan untuk tidak terbatas</td></tr><tr><td><strong>Rate Limit Upload</strong></td><td>Batas kecepatan upload, misal <code>2M</code></td></tr><tr><td><strong>Rate Limit Download</strong></td><td>Batas kecepatan download, misal <code>5M</code></td></tr><tr><td><strong>Harga (Rp)</strong></td><td>Harga jual voucher</td></tr><tr><td><strong>PPN</strong></td><td>Persentase PPN jika dikenakan</td></tr></tbody></table><ol start="4"><li>Klik <strong>Simpan</strong> — profil akan di-sync ke Hotspot User Profile di MikroTik</li></ol><hr><h2 id="contoh-profil-umum" tabindex="-1">Contoh Profil Umum <a class="header-anchor" href="#contoh-profil-umum" aria-label="Permalink to &quot;Contoh Profil Umum&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nama</th><th>Validitas</th><th>Rate Limit</th><th>Harga</th></tr></thead><tbody><tr><td>Paket 1 Jam</td><td>60 menit</td><td>2M/5M</td><td>Rp 2.000</td></tr><tr><td>Paket Harian</td><td>1 hari</td><td>5M/10M</td><td>Rp 5.000</td></tr><tr><td>Paket Mingguan</td><td>7 hari</td><td>5M/10M</td><td>Rp 25.000</td></tr><tr><td>Paket Bulanan</td><td>30 hari</td><td>10M/20M</td><td>Rp 75.000</td></tr></tbody></table><hr><h2 id="edit-hapus-profil" tabindex="-1">Edit &amp; Hapus Profil <a class="header-anchor" href="#edit-hapus-profil" aria-label="Permalink to &quot;Edit &amp; Hapus Profil&quot;">​</a></h2><p>Klik ikon <strong>pensil</strong> atau <strong>hapus</strong> di baris profil.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Menghapus profil akan menghapusnya dari MikroTik juga. Voucher yang sudah dibuat dengan profil ini tidak terpengaruh, namun tidak bisa membuat voucher baru dengan profil yang sudah dihapus.</p></div>',14)])])}const c=a(i,[["render",e]]);export{m as __pageData,c as default};
